#pragma once

#include <juce_core/juce_core.h>
#include <array>
#include <vector>

//==============================================================================
//  Real-drummer feel (plan Step 32)
//
//  Measured from the Groove MIDI Dataset (Google LLC, CC BY 4.0): for each
//  style, how early or late real drummers play each kind of hit at each 16th
//  of a 4/4 bar, how much that varies, and how hard they play it. Plus short
//  grooves played by the drummers themselves.
//
//  The data (RealFeel.cpp) is generated by tools/make_feel.py during the
//  GitHub build. Without it (fromRealDrummers() false) the lists are empty.
//==============================================================================
namespace RealFeel
{
    enum Kind { kick, snare, hiHat, cymbal, tom, numKinds };

    struct Cell
    {
        int count;          // how many hits the drummers played here
        float offset;       // average: + late, - early, in 16ths
        float spread;       // how much it varied, in 16ths
        float velocity;     // average strength (1-127)
    };

    struct Style
    {
        const char* name;                                   // "Gospel"
        const char* key;                                    // "gospel"
        int performances;
        std::array<Cell, numKinds * 16> cells;              // kind * 16 + 16th of the bar
        std::array<float, numKinds> kindVelocity;           // average strength of each kind
    };

    struct Hit { double beat; int note, velocity; };

    struct Groove
    {
        const char* name;                                   // "Gospel 1 (84 BPM)"
        const char* style;
        int bpm;
        double lengthBeats;                                 // 8: two bars of 4/4
        std::vector<Hit> hits;
    };

    bool fromRealDrummers();
    const char* credit();
    const std::vector<Style>& styles();
    const std::vector<Groove>& grooves();

    inline const Style* findStyle (const juce::String& name)
    {
        for (auto& s : styles())
            if (name.equalsIgnoreCase (s.name) || name.equalsIgnoreCase (s.key))
                return &s;
        return nullptr;
    }

    // General MIDI drum note -> kind of hit (-1: percussion, left as it is)
    inline int kindOf (int note)
    {
        switch (note)
        {
            case 35: case 36:                               return kick;
            case 37: case 38: case 40: case 39:             return snare;
            case 42: case 44: case 46:                      return hiHat;
            case 49: case 51: case 52: case 53: case 55: case 57: case 59: return cymbal;
            case 41: case 43: case 45: case 47: case 48: case 50:          return tom;
            default:                                        return -1;
        }
    }

    // Where a hit on the grid lands with this feel, and how hard.
    // gridBeat: the note's place on the grid, counted from the start of its bar.
    struct Placed { double offsetBeats; int velocity; };

    inline Placed place (const Style& style, int note, double beatInBar, int velocity, juce::Random& random)
    {
        const int kind = kindOf (note);
        if (kind < 0)
        {
            // Hand percussion: follows the hi-hat's timing, keeps its own strength
            if (note < 54 || note > 87)
                return { 0.0, velocity };
        }
        const int k = kind < 0 ? (int) hiHat : kind;
        const int sixteenth = ((int) std::lround (beatInBar * 4.0) % 16 + 16) % 16;
        const auto& c = style.cells[(size_t) (k * 16 + sixteenth)];

        // Timing: the drummers' average push or lay-back, plus a little of their natural variation
        auto offset16 = c.offset + (float) ((random.nextDouble() * 2.0 - 1.0) * c.spread * 0.6);
        offset16 = juce::jlimit (-0.4f, 0.4f, offset16);

        // Strength: the drummers' accents, mixed with the pattern's own
        int newVelocity = velocity;
        if (kind >= 0 && style.kindVelocity[(size_t) kind] > 1.0f && c.velocity > 1.0f)
        {
            const auto accent = c.velocity / style.kindVelocity[(size_t) kind];
            newVelocity = juce::roundToInt (velocity * std::pow (accent, 0.7f)) + random.nextInt ({ -4, 5 });
        }
        return { offset16 * 0.25, juce::jlimit (1, 127, newVelocity) };
    }
}
